package net.civeira.phylax.features.document.theme.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.features.document.theme.domain.Theme;
import net.civeira.phylax.features.document.theme.domain.gateway.ThemeCursor;
import net.civeira.phylax.features.document.theme.domain.gateway.ThemeFilter;

class ThemeSlider extends Slider<Theme> {

  /**
   * @autogenerated SlideGenerator
   */
  private final ThemeCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final ThemeFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<ThemeFilter, ThemeCursor, Iterator<Theme>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  ThemeSlider(final Iterator<Theme> multi, final int limit,
      final BiFunction<ThemeFilter, ThemeCursor, Iterator<Theme>> gateway, final ThemeFilter filter,
      final ThemeCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param themes
   * @param limit
   * @return
   */
  @Override
  public Iterator<Theme> next(List<Theme> themes, int limit) {
    Theme last = themes.get(themes.size() - 1);
    ThemeCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
